        if (Js.T(Js.T(s.sleep?.asleep)))
        {
            return $"{Js.Str(s.name)} is asleep";
        }
        if (state.tick < s.story.nextTalk)
        {
            return $"{Js.Str(s.name)} doesn't want to talk again yet";
        }
        s.story.nextTalk = state.tick + TALK_EVERY;
