        Wellbeing.socialise(s, Wellbeing.TALK_SOCIAL);
        var lines = StoryMod.storyLines(s.story);
        if (s.story.told < lines.length)
        {
            Events.logEvent(state, $"{Js.Str(s.name)}: \"{Js.Str(Js.Get(lines, s.story.told))}\"");
            s.story.told += 1;
            if (s.story.told == 1)
