        {
            var kind = TASK_ORDER.find((k) => (!s.story.asked.includes(k) && (s.story.told >= Js.Get(TOLD_BEFORE, k))) && wants(state, s, k));
            if (Js.T(kind))
            {
                offerTask(state, s, kind);
            }
        }
        return null;
    }

    /// <summary>Whether this task fits their story (and the world: medicine needs a neighbour).</summary>
    public static bool wants(SimState state, Survivor s, string k)
    {
