    /// <summary>A free floor tile out in the world for a task, generating the land there if need be.</summary>
    public static Point? taskSpot(SimState state, Survivor s, string kind)
    {
        if (kind == "radio")
        {
            return Js.CopyAs<Point>(s.pos);
        }
        if (kind == "medicine")
        {
            var friend = friendFor(state, s);
            return Js.T(friend) ? new Point { x = Js.I(friend.x), y = Js.I(friend.y) } : null;
        }
        var n = Hash.idNumber(s.id);
        var k = TASK_ORDER.indexOf(kind);
        var angle = (Hash.hashRoll(n, k, 0x7a5) * JsMath.PI) * 2;
        var dist = TASK_MIN + (Hash.hashRoll(n, k, 0x7a6) * TASK_SPREAD);
        var __d1 = state.grid;
        var width = __d1.width;
        var height = __d1.height;
        Point p = new Point { x = Js.I(JsMath.max(1, JsMath.min(width - 2, JsMath.round(s.pos.x + (JsMath.cos(angle) * dist))))), y = Js.I(JsMath.max(1, JsMath.min(height - 2, JsMath.round(s.pos.y + (JsMath.sin(angle) * dist))))) };
        Worldgen.ensureGeneratedAround(state, p);
        return Space.nearestTile(state.grid, p, (x, y) => (((Grids.inBounds(state.grid, x, y) && (Grids.getTile(state.grid, x, y) == "floor")) && Grids.isWalkable(state.grid, x, y)) && !Js.T(FurnitureMod.furnitureAt(state, x, y))) && !Js.T(Items.itemAt(state, x, y)));
    }

    public static bool near(Point a, Point b, double r)
    {
        return JsMath.max(JsMath.abs(a.x - b.x), JsMath.abs(a.y - b.y)) <= r;
    }

    /// <summary>Checks tasks for being done (or no longer doable). Every 10 ticks.</summary>
    public static void updateTasks(SimState state)
    {
        if (((state.tick % 10) != 0) || (state.tasks.length == 0))
        {
            return;
        }
        var graves = state.tasks.some((t) => t.kind == "bury") ? Rooms.completeRooms(state, "graveyard") : new JsSet<double>();
        foreach (var task in Js.Iter((state.tasks).ToList()))
        {
            var giver = state.survivors.find((s) => s.id == task.giverId);
            if (!Js.T(giver))
            {
                drop(state, task);
                continue;
            }
            var outcome = check(state, task, giver, graves);
            if (outcome == null)
            {
                continue;
            }
            drop(state, task);
            if (Js.T(outcome))
            {
                reward(state, task, giver);
            }
        }
    }

    /// <summary>True: done. False: can't be done any more. Null: still open.</summary>
    public static bool? check(SimState state, Task task, Survivor giver, JsSet<double> graves)
    {
        Point spot = new Point { x = Js.I(task.x), y = Js.I(task.y) };
        switch (task.kind)
        {
            case "home":
                {
                    {
                    var you = ControlMod.controlled(state);
                    return (near(giver.pos, spot, 2) || ((you != null) && near(you.pos, spot, 2))) ? true : null;
                }
                }
            case "bury":
                {
                    {
                    var body = Js.T(task.targetId) ? Items.getItem(state, task.targetId) : null;
                    if (!Js.T(body))
                    {
                        return fail(state, giver, $"Nobody can bury {Js.Str(giver.story.lost.name)} now.");
                    }
                    return (Js.T(body.pos) && graves.has(Rooms.labelAt(state, body.pos.x, body.pos.y))) ? true : null;
                }
                }
            case "pet":
                {
                    {
                    var dog = Js.T(task.targetId) ? Dogs.getDogById(state, task.targetId) : null;
                    if (!Js.T(dog))
                    {
                        return fail(state, giver, $"{Js.Str(giver.story.pet)} is gone.");
                    }
                    return Js.T(dog.waiting) ? null : true;
                }
                }
            case "burn":
                {
                    return state.fires.some((f) => near(f, spot, 1)) ? true : null;
                }
            case "radio":
                {
                    return ((Time.tickOfDay(state.tick) == (12 * Time.TICKS_PER_HOUR)) && Radio.hasRadio(state)) ? callOut(state, task, giver) : null;
                }
            case "medicine":
                {
                    {
                    var friend = state.settlements.find((n) => n.id == task.targetId);
                    if (!Js.T(friend) || (friend.people <= 0))
                    {
                        return fail(state, giver, "nobody is left there to help.");
                    }
                    var bearer = state.survivors.find((s) => (Js.T(s.carrying) && (Items.getItem(state, s.carrying)?.kind == "medicine")) && near(s.pos, spot, MEDICINE_REACH));
                    if (!Js.T(bearer))
                    {
                        return null;
                    }
                    var medicine = Js.NN(Items.getItem(state, Js.NN(bearer.carrying)));
                    bearer.carrying = null;
                    Items.removeItem(state, medicine);
                    Settlements.adjustReputation(state, friend, 15);
                    Events.logEvent(state, $"{Js.Str(bearer.name)} brought medicine to {Js.Str(giver.name)}'s friend at {Js.Str(friend.name)}");
                    return true;
                }
                }
        }
        throw new InvalidOperationException("unreachable: every case returns");
    }

    /// <summary>Noon on the radio: the missing relative answers (and sets out to join you), or nobody does.</summary>
    public static bool? callOut(SimState state, Task task, Survivor giver)
    {
        var __d2 = giver.story;
        var lost = __d2.lost;
        if (Hash.hashRoll(Hash.idNumber(task.id), 0xca11) >= ANSWER_CHANCE)
        {
            Mood.addThought(state, giver, "lostHope");
            Resolve.steel(giver, -SILENCE_RESOLVE);
            Events.logEvent(state, $"{Js.Str(giver.name)} called for {Js.Str(lost.name)} on the radio until dark. Nobody answered.");
            return false;
        }
        var spot = Wanderers.frontierSpot(state, new JsSet<string>());
        if (!Js.T(spot))
        {
            return null;
        }
        var w = Wanderers.addWanderer(state, spot.x, spot.y);
        w.name = lost.name;
        Events.logEvent(state, $"{Js.Str(lost.name)} answered the radio! They're at ({Js.Str(spot.x)}, {Js.Str(spot.y)}), waiting to be taken in.");
        return true;
    }

    public static bool fail(SimState state, Survivor giver, string why)
    {
        Events.logEvent(state, $"{Js.Str(giver.name)}'s request can't be done: {Js.Str(why)}");
        return false;
    }

    public static void drop(SimState state, Task task)
    {
        state.tasks.splice(state.tasks.indexOf(task), 1);
    }

    public static void reward(SimState state, Task task, Survivor giver)
    {
        Mood.addThought(state, giver, Js.Get(REWARD, task.kind));
        Resolve.steel(giver, (task.kind == "radio") ? REUNITED_RESOLVE : TASK_RESOLVE);
        var you = ControlMod.controlled(state);
        if (Js.T(you) && (you != giver))
        {
            warm(giver, you, TASK_OPINION);
        }
        var done = new JsRecord<string> { ["home"] = $"{Js.Str(giver.name)}'s old place has been seen to", ["bury"] = $"{Js.Str(giver.story.lost.name)} has a grave now. {Js.Str(giver.name)} can rest a little", ["pet"] = $"{Js.Str(giver.story.pet)} has been found", ["burn"] = $"The place {Js.Str(giver.name)} couldn't stop seeing is ash", ["radio"] = $"{Js.Str(giver.name)} is crying, and not from grief", ["medicine"] = $"{Js.Str(giver.name)}'s friend has their medicine" }[Js.Str(task.kind)];
        Events.logEvent(state, $"{Js.Str(done)}.");
    }

    /// <summary>Open tasks given by a survivor, as text.</summary>
    public static List<string> describeTasks(SimState state, Survivor s)
    {
        return state.tasks.filter((t) => t.giverId == s.id).map((t) =>
        {
            var what = new JsRecord<string> { ["home"] = "see their old place", ["bury"] = $"bury {Js.Str(s.story.lost.name)}", ["pet"] = $"find {Js.Str(s.story.pet)}", ["burn"] = "burn down the place", ["radio"] = $"call for {Js.Str(s.story.lost.name)} on a powered radio (at noon)", ["medicine"] = "take medicine to their friend" }[Js.Str(t.kind)];
            return $"asks you to {Js.Str(what)} at ({Js.Str(t.x)}, {Js.Str(t.y)})";
        });
    }
